-- Arbeitsrecht Berufsbildung > Arbeitsverträge > Vergütungsvereinbarung
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb die Vergütung eines Fachinformatikers schriftlich nachweisen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt den schriftlichen Nachweis der Vergütung"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Vergütungsvereinbarung eines Fachinformatikers mündlich getroffen werden, ohne schriftlichen Nachweis?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG fordert schriftlichen Nachweis"}, {"text": "Ja", "correct": false, "because": "Mündlich nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Vergütungsvereinbarung eines Fachinformatikers auch Überstundenvergütung enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt Angaben zur Überstundenvergütung"}, {"text": "Nein", "correct": false, "because": "Überstunden sind Teil der Vergütungsregelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb die Vergütung eines Fachinformatikers per E-Mail ohne Unterschrift nachweisen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG verlangt eigenhändige Unterschrift"}, {"text": "Ja", "correct": false, "because": "E-Mail genügt nicht der Schriftform"}]'),
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker Anspruch auf eine schriftliche Vergütungsvereinbarung?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 NachwG und § 17 BBiG sichern dieses Recht"}, {"text": "Nein", "correct": false, "because": "Nachweis ist Pflicht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Betrieb, die Vergütung eines Fachinformatikers schriftlich nachzuweisen?', 2, '[{"text": "§ 2 NachwG", "correct": true, "because": "Regelt die Schriftform der Vergütung"}, {"text": "§ 22 BBiG", "correct": false, "because": "Bezieht sich auf Kündigungen"}, {"text": "§ 13 BBiG", "correct": false, "because": "Regelt Pflichten des Auszubildenden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss in der schriftlichen Vergütungsvereinbarung eines Fachinformatikers enthalten sein?', 3, '[{"text": "Höhe der monatlichen Vergütung", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG fordert dies"}, {"text": "Nur die Zahlungsweise", "correct": false, "because": "Zu unvollständig"}, {"text": "Persönliche Präferenzen", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Bis wann muss ein Betrieb die Vergütungsvereinbarung eines Fachinformatikers schriftlich nachweisen?', 2, '[{"text": "Spätestens 1 Monat nach Beginn", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}, {"text": "Innerhalb von 6 Monaten", "correct": false, "because": "Zu spät"}, {"text": "Jederzeit während der Ausbildung", "correct": false, "because": "Frist ist vorgegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, die Vergütungsvereinbarung eines Fachinformatikers schriftlich nachzuweisen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 2 NachwG verpflichtet den Arbeitgeber"}, {"text": "Die IHK", "correct": false, "because": "IHK hat keine Rolle dabei"}, {"text": "Der Auszubildende", "correct": false, "because": "Nicht seine Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb die Vergütungsvereinbarung eines Fachinformatikers nicht schriftlich nachweist?', 3, '[{"text": "Der Auszubildende kann Nachbesserung verlangen", "correct": true, "because": "§ 2 NachwG ist einklagbar"}, {"text": "Der Vertrag wird ungültig", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Keine Konsequenzen", "correct": false, "because": "Verstoß hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente müssen in der Vergütungsvereinbarung eines Fachinformatikers schriftlich nachgewiesen werden?', 4, '[{"text": "Monatliche Grundvergütung", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG fordert dies"}, {"text": "Überstundenvergütung", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt dies"}, {"text": "Persönliche Wünsche zur Vergütung", "correct": false, "because": "Nicht relevant"}, {"text": "Sonderzahlungen wie Weihnachtsgeld", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG schreibt dies vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen gelten für die schriftliche Vergütungsvereinbarung eines Fachinformatikers?', 3, '[{"text": "Schriftform mit Unterschrift", "correct": true, "because": "§ 2 NachwG verlangt dies"}, {"text": "Nachweis innerhalb eines Monats", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}, {"text": "Elektronische Form genügt", "correct": false, "because": "Nicht ausreichend"}, {"text": "Angabe der Vergütungshöhe", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG fordert dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb bei der Vergütungsvereinbarung eines Fachinformatikers beachten?', 4, '[{"text": "Schriftlichen Nachweis erstellen", "correct": true, "because": "§ 2 NachwG schreibt dies vor"}, {"text": "Eigenhändige Unterschrift leisten", "correct": true, "because": "Schriftform erfordert dies"}, {"text": "Nur mündlich vereinbaren", "correct": false, "because": "Nicht ausreichend"}, {"text": "Innerhalb eines Monats übergeben", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen, wenn ein Betrieb die Vergütungsvereinbarung eines Fachinformatikers nicht schriftlich nachweist?', 3, '[{"text": "Nachbesserung durch den Auszubildenden forderbar", "correct": true, "because": "§ 2 NachwG ist einklagbar"}, {"text": "Bußgelder möglich", "correct": true, "because": "Verstoß kann sanktioniert werden"}, {"text": "Automatische Vertragsauflösung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK kann eingreifen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen müssen in der Vergütungsvereinbarung eines Fachinformatikers nicht enthalten sein?', 3, '[{"text": "Grundvergütung", "correct": false, "because": "§ 2 Abs. 1 Nr. 6 NachwG fordert dies"}, {"text": "Persönliche Präferenzen zur Vergütung", "correct": true, "because": "Nicht wesentlich"}, {"text": "Überstundenvergütung", "correct": false, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt dies"}, {"text": "Sonderzahlungen", "correct": false, "because": "§ 2 Abs. 1 Nr. 6 NachwG schreibt dies vor"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Vergütung eines Fachinformatikers muss schriftlich nachgewiesen werden. b) Eine E-Mail ohne Unterschrift genügt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform erforderlich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 2 NachwG verlangt die Angabe der Vergütungshöhe. b) Der Nachweis muss innerhalb eines Monats erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 und Frist bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Überstundenvergütung muss in der Vergütungsvereinbarung enthalten sein. b) Eine mündliche Vereinbarung ist ausreichend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überstunden Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker kann die schriftliche Vergütungsvereinbarung einfordern. b) Der Nachweis ist nur bei Kündigung erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einfordern möglich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) § 2 NachwG fordert die Schriftform für die Vergütung. b) Eine Unterschrift ist nicht erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

